write: {"content": "import csv

def bubble_sort(items, key=lambda x: x):
    arr = items[:]
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if key(arr[j]) > key(arr[j+1]):
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def main():
    with open('компоненты.csv', 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter=';')
        rows = list(reader)

    header, data = rows[0], rows[1:]
    sorted_data = bubble_sort(data, key=lambda x: x[0])

    print(';'.join(header))
    for row in sorted_data:
        print(';'.join(row))

if __name__ == '__main__':
    main()
